919	 * 与 connectToPeer 区别：对端后端会识别出已知联系人并自动接受，无需对端用户确认。
920	 */
921	async function autoReconnect(uuid) {
922	    // 不重复连接
923	    if (activeChats.has(uuid)) return;
924	
925	    const peer = onlinePeers.get(uuid);
