945	                type: 'connect_request',
946	                uuid: myInfo.uuid,
947	                name: myInfo.name,
948	                token: myInfo.token,
949	                ip: myInfo.ip,
950	                ws_port: myInfo.ws_port,
951	                have_you: contacts.has(uuid),
952	            }));
953	        };
954	
955	        ws.onmessage = (e) => {
956	            const msg = JSON.parse(e.data);
957	            if (msg.type === 'connect_accepted') {
958	                activeChats.set(uuid, ws);
959	                connectedPeers.add(uuid);
960	                markConnected(uuid);
